    """
    def parse_value(val):
        if isinstance(val, str):
            val = val.replace(',', '.')
            return float(val)
        return float(val)

    a_parsed = parse_value(a)
    b_parsed = parse_value(b)

    if a_parsed == b_parsed:
        return None
    elif a_parsed > b_parsed:
        return a
    else:
